SET NAMES utf8mb4;

-- ========== domain: base_data (基础主数据) ==========
CREATE TABLE `goods_category` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `parent_id` BIGINT NULL COMMENT '上级分类，一级分类为空',
  `level` INT COMMENT '层级 1/2/3',
  `name` VARCHAR(64) COMMENT '分类名称',
  `sort` INT DEFAULT 0 COMMENT '排序号',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `fk_goods_category_parent_id` FOREIGN KEY (`parent_id`) REFERENCES `goods_category`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商品分类';

CREATE TABLE `unit` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `name` VARCHAR(32) COMMENT '单位名称，如 斤/箱/份',
  `sort` INT DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='计量单位';

CREATE TABLE `tax_rate` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `name` VARCHAR(64) COMMENT '税率名称',
  `rate` DECIMAL(5,2) COMMENT '百分比数值'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='税率';

CREATE TABLE `goods` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `name` VARCHAR(128) COMMENT '商品名称',
  `category_id` BIGINT NOT NULL,
  `unit_id` BIGINT NOT NULL,
  `tax_rate_id` BIGINT NULL COMMENT '适用税率',
  `alias` VARCHAR(128) COMMENT '别名，用于客户下单时匹配',
  `spec` VARCHAR(64) COMMENT '规格，如 500g/袋',
  `status` VARCHAR(32) DEFAULT 'normal' COMMENT '启用状态',
  CHECK (`status` IN ('normal', 'stopped')),
  `remark` VARCHAR(255),
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `fk_goods_category_id` FOREIGN KEY (`category_id`) REFERENCES `goods_category`(`id`),
  CONSTRAINT `fk_goods_unit_id` FOREIGN KEY (`unit_id`) REFERENCES `unit`(`id`),
  CONSTRAINT `fk_goods_tax_rate_id` FOREIGN KEY (`tax_rate_id`) REFERENCES `tax_rate`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商品（SPU）';

CREATE TABLE `goods_sku` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `goods_id` BIGINT NOT NULL,
  `sku_name` VARCHAR(128) COMMENT 'SKU 名称',
  `barcode` VARCHAR(64) COMMENT '条码',
  `price` DECIMAL(12,2) COMMENT '参考售价',
  `status` VARCHAR(32) DEFAULT 'normal',
  CHECK (`status` IN ('normal', 'stopped')),
  CONSTRAINT `fk_goods_sku_goods_id` FOREIGN KEY (`goods_id`) REFERENCES `goods`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商品 SKU';

CREATE TABLE `region` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `name` VARCHAR(64),
  `parent_id` BIGINT NULL COMMENT '上级区域',
  `sort` INT DEFAULT 0,
  CONSTRAINT `fk_region_parent_id` FOREIGN KEY (`parent_id`) REFERENCES `region`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='区域';

-- ========== domain: procurement (采购管理) ==========
CREATE TABLE `supplier` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `name` VARCHAR(128) COMMENT '供应商名称',
  `external_code` VARCHAR(64) COMMENT '外部平台编号（双轨同步用）',
  `contact_name` VARCHAR(64),
  `contact_phone` VARCHAR(32),
  `address` VARCHAR(255),
  `settle_type` VARCHAR(32) DEFAULT 'month' COMMENT '结算周期',
  CHECK (`settle_type` IN ('month', 'half_month', 'cash')),
  `remark` VARCHAR(255),
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `status` VARCHAR(32) DEFAULT 'normal' COMMENT '状态（lockable 自动派生）',
  CHECK (`status` IN ('normal', 'locked')),
  `lock_operator` VARCHAR(64) COMMENT '禁用操作人（lockable 自动派生）',
  `lock_time` DATETIME COMMENT '禁用时间（lockable 自动派生）'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='供应商';

CREATE TABLE `buyer` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `name` VARCHAR(64),
  `phone` VARCHAR(32),
  `group_tag` VARCHAR(32) DEFAULT 'fresh' COMMENT '生鲜组/干货组',
  CHECK (`group_tag` IN ('fresh', 'dry')),
  `status` VARCHAR(32) DEFAULT 'normal' COMMENT '状态（lockable 自动派生）',
  CHECK (`status` IN ('normal', 'locked')),
  `lock_operator` VARCHAR(64) COMMENT '禁用操作人（lockable 自动派生）',
  `lock_time` DATETIME COMMENT '禁用时间（lockable 自动派生）'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='采购员';

CREATE TABLE `supplier_goods` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `supplier_id` BIGINT NOT NULL,
  `goods_id` BIGINT NOT NULL,
  `supply_price` DECIMAL(12,2) COMMENT '供货价',
  `is_primary` TINYINT(1) DEFAULT 0 COMMENT '是否主供应商',
  CONSTRAINT `fk_supplier_goods_supplier_id` FOREIGN KEY (`supplier_id`) REFERENCES `supplier`(`id`),
  CONSTRAINT `fk_supplier_goods_goods_id` FOREIGN KEY (`goods_id`) REFERENCES `goods`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='供应商-商品绑定';

CREATE TABLE `supplier_price_sheet` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `sheet_no` VARCHAR(32) COMMENT '报价单号',
  `supplier_id` BIGINT NOT NULL,
  `sheet_date` DATE COMMENT '报价日期',
  `status` VARCHAR(32) DEFAULT 'draft',
  CHECK (`status` IN ('draft', 'submitted', 'approved', 'rejected')),
  CONSTRAINT `fk_supplier_price_sheet_supplier_id` FOREIGN KEY (`supplier_id`) REFERENCES `supplier`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='供应商报价单';

CREATE TABLE `supplier_price_item` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `sheet_id` BIGINT NOT NULL,
  `goods_id` BIGINT NOT NULL,
  `price` DECIMAL(12,2),
  CONSTRAINT `fk_supplier_price_item_sheet_id` FOREIGN KEY (`sheet_id`) REFERENCES `supplier_price_sheet`(`id`),
  CONSTRAINT `fk_supplier_price_item_goods_id` FOREIGN KEY (`goods_id`) REFERENCES `goods`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='报价明细';

CREATE TABLE `purchase_task` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `task_no` VARCHAR(32) COMMENT '任务单号',
  `delivery_date` DATE COMMENT '配送日期',
  `task_type` VARCHAR(32) DEFAULT 'fresh' COMMENT '生鲜/干货导单流程',
  CHECK (`task_type` IN ('fresh', 'dry')),
  `status` VARCHAR(32) DEFAULT 'draft' COMMENT '生命周期见 workflow',
  CHECK (`status` IN ('draft', 'released', 'executing', 'completed', 'cancelled')),
  `released_at` DATETIME COMMENT '发布时间',
  `released_by` VARCHAR(64),
  `remark` VARCHAR(255),
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `created_by` VARCHAR(64) COMMENT '创建人（auditable 自动派生）',
  `updated_at` DATETIME COMMENT '更新时间（auditable 自动派生）'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='采购任务';

CREATE TABLE `purchase_task_item` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `task_id` BIGINT NOT NULL,
  `goods_id` BIGINT NOT NULL,
  `plan_qty` DECIMAL(12,2) COMMENT '需求数量（汇总自销售订单）',
  `actual_qty` DECIMAL(12,2) COMMENT '实采数量',
  `supplier_id` BIGINT NULL COMMENT '指定供应商',
  `buyer_id` BIGINT NULL COMMENT '指定采购员',
  `purchase_remark` VARCHAR(255) COMMENT '采购说明/加工要求',
  CONSTRAINT `fk_purchase_task_item_task_id` FOREIGN KEY (`task_id`) REFERENCES `purchase_task`(`id`),
  CONSTRAINT `fk_purchase_task_item_goods_id` FOREIGN KEY (`goods_id`) REFERENCES `goods`(`id`),
  CONSTRAINT `fk_purchase_task_item_supplier_id` FOREIGN KEY (`supplier_id`) REFERENCES `supplier`(`id`),
  CONSTRAINT `fk_purchase_task_item_buyer_id` FOREIGN KEY (`buyer_id`) REFERENCES `buyer`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='采购任务明细';

CREATE TABLE `goods_supply_ratio` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `goods_id` BIGINT NOT NULL,
  `supplier_id` BIGINT NOT NULL,
  `delivery_date` DATE COMMENT '生效配送日期',
  `ratio` DECIMAL(5,2) COMMENT '分配百分比',
  CONSTRAINT `fk_goods_supply_ratio_goods_id` FOREIGN KEY (`goods_id`) REFERENCES `goods`(`id`),
  CONSTRAINT `fk_goods_supply_ratio_supplier_id` FOREIGN KEY (`supplier_id`) REFERENCES `supplier`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='供应商比例分配';

-- ========== domain: sales (销售管理) ==========
CREATE TABLE `customer` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `code` VARCHAR(32) COMMENT '客户编号，如 C000000001',
  `external_code` VARCHAR(64) COMMENT '外部平台客户编号（同步用）',
  `name` VARCHAR(128) COMMENT '客户名称',
  `client_type` VARCHAR(32) DEFAULT 'company' COMMENT '企业客户/零售客户',
  CHECK (`client_type` IN ('company', 'retail')),
  `contact_name` VARCHAR(64),
  `contact_phone` VARCHAR(32),
  `address` VARCHAR(255) COMMENT '收货地址',
  `region_id` BIGINT NULL,
  `pay_type` VARCHAR(32) DEFAULT 'pay_later' COMMENT '先款/先货',
  CHECK (`pay_type` IN ('pay_first', 'pay_later')),
  `pay_cycle` VARCHAR(32) DEFAULT 'month',
  CHECK (`pay_cycle` IN ('day', 'week', 'month')),
  `account_manager` VARCHAR(64) COMMENT '客户经理',
  `api_key` VARCHAR(64) COMMENT '对外下单 API 凭证',
  `remark` VARCHAR(255),
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `status` VARCHAR(32) DEFAULT 'normal' COMMENT '状态（lockable 自动派生）',
  CHECK (`status` IN ('normal', 'locked')),
  `lock_operator` VARCHAR(64) COMMENT '禁用操作人（lockable 自动派生）',
  `lock_time` DATETIME COMMENT '禁用时间（lockable 自动派生）',
  CONSTRAINT `fk_customer_region_id` FOREIGN KEY (`region_id`) REFERENCES `region`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='客户';

CREATE TABLE `sales_order` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `order_no` VARCHAR(32) COMMENT '订单号',
  `customer_id` BIGINT NOT NULL,
  `delivery_date` DATE COMMENT '配送日期',
  `total_amount` DECIMAL(12,2) DEFAULT 0,
  `source` VARCHAR(32) DEFAULT 'manual' COMMENT '订单来源',
  CHECK (`source` IN ('manual', 'api', 'miniapp', 'import')),
  `status` VARCHAR(32) DEFAULT 'draft' COMMENT '生命周期见 workflow',
  CHECK (`status` IN ('draft', 'confirmed', 'sorting', 'delivering', 'signed', 'cancelled')),
  `remark` VARCHAR(255),
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `created_by` VARCHAR(64) COMMENT '创建人（auditable 自动派生）',
  `updated_at` DATETIME COMMENT '更新时间（auditable 自动派生）',
  CONSTRAINT `fk_sales_order_customer_id` FOREIGN KEY (`customer_id`) REFERENCES `customer`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='销售订单';

CREATE TABLE `sales_order_item` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `order_id` BIGINT NOT NULL,
  `goods_id` BIGINT NOT NULL,
  `qty` DECIMAL(12,2),
  `price` DECIMAL(12,2),
  `process_requirement` VARCHAR(255) COMMENT '加工要求，如 去皮/切块',
  `item_remark` VARCHAR(255),
  CONSTRAINT `fk_sales_order_item_order_id` FOREIGN KEY (`order_id`) REFERENCES `sales_order`(`id`),
  CONSTRAINT `fk_sales_order_item_goods_id` FOREIGN KEY (`goods_id`) REFERENCES `goods`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='订单明细';

-- ========== domain: inventory (库存管理) ==========
CREATE TABLE `warehouse` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `name` VARCHAR(64),
