CREATE TABLE `stock_in` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `in_no` VARCHAR(32),
  `warehouse_id` BIGINT NOT NULL,
  `supplier_id` BIGINT NULL COMMENT '采购入库时的供应商',
  `in_type` VARCHAR(32) DEFAULT 'purchase',
  CHECK (`in_type` IN ('purchase', 'return', 'adjust', 'other')),
  `status` VARCHAR(32) DEFAULT 'draft',
  CHECK (`status` IN ('draft', 'pending_review', 'posted', 'rejected')),
  `total_amount` DECIMAL(12,2) DEFAULT 0,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `created_by` VARCHAR(64) COMMENT '创建人（auditable 自动派生）',
  `updated_at` DATETIME COMMENT '更新时间（auditable 自动派生）',
  CONSTRAINT `fk_stock_in_warehouse_id` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouse`(`id`),
  CONSTRAINT `fk_stock_in_supplier_id` FOREIGN KEY (`supplier_id`) REFERENCES `supplier`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='入库单';

CREATE TABLE `stock_in_item` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `stock_in_id` BIGINT NOT NULL,
  `goods_id` BIGINT NOT NULL,
  `qty` DECIMAL(12,2),
  `price` DECIMAL(12,2),
  `batch_no` VARCHAR(64) COMMENT '关联溯源批次号',
  CONSTRAINT `fk_stock_in_item_stock_in_id` FOREIGN KEY (`stock_in_id`) REFERENCES `stock_in`(`id`),
  CONSTRAINT `fk_stock_in_item_goods_id` FOREIGN KEY (`goods_id`) REFERENCES `goods`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='入库明细';

CREATE TABLE `stock_out` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `out_no` VARCHAR(32),
  `warehouse_id` BIGINT NOT NULL,
  `customer_id` BIGINT NULL COMMENT '销售出库时的客户',
  `out_type` VARCHAR(32) DEFAULT 'sale',
  CHECK (`out_type` IN ('sale', 'purchase_return', 'adjust', 'other')),
  `status` VARCHAR(32) DEFAULT 'draft',
  CHECK (`status` IN ('draft', 'pending_review', 'posted', 'rejected')),
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `created_by` VARCHAR(64) COMMENT '创建人（auditable 自动派生）',
  `updated_at` DATETIME COMMENT '更新时间（auditable 自动派生）',
  CONSTRAINT `fk_stock_out_warehouse_id` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouse`(`id`),
  CONSTRAINT `fk_stock_out_customer_id` FOREIGN KEY (`customer_id`) REFERENCES `customer`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='出库单';

CREATE TABLE `stock_out_item` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `stock_out_id` BIGINT NOT NULL,
  `goods_id` BIGINT NOT NULL,
  `qty` DECIMAL(12,2),
  `price` DECIMAL(12,2),
  `batch_no` VARCHAR(64),
  CONSTRAINT `fk_stock_out_item_stock_out_id` FOREIGN KEY (`stock_out_id`) REFERENCES `stock_out`(`id`),
  CONSTRAINT `fk_stock_out_item_goods_id` FOREIGN KEY (`goods_id`) REFERENCES `goods`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='出库明细';

CREATE TABLE `stocktake` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `warehouse_id` BIGINT NOT NULL,
  `take_date` DATE,
  `status` VARCHAR(32) DEFAULT 'draft',
  CHECK (`status` IN ('draft', 'counting', 'submitted', 'posted')),
  CONSTRAINT `fk_stocktake_warehouse_id` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouse`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='盘点单';

CREATE TABLE `stocktake_item` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `stocktake_id` BIGINT NOT NULL,
  `goods_id` BIGINT NOT NULL,
  `book_qty` DECIMAL(12,2) COMMENT '账面数量',
  `actual_qty` DECIMAL(12,2) COMMENT '实盘数量',
  CONSTRAINT `fk_stocktake_item_stocktake_id` FOREIGN KEY (`stocktake_id`) REFERENCES `stocktake`(`id`),
  CONSTRAINT `fk_stocktake_item_goods_id` FOREIGN KEY (`goods_id`) REFERENCES `goods`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='盘点明细';

CREATE TABLE `stock_adjust` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `adjust_no` VARCHAR(32),
  `warehouse_id` BIGINT NOT NULL,
  `adjust_type` VARCHAR(32) DEFAULT 'loss' COMMENT '报损/损耗/盘盈',
  CHECK (`adjust_type` IN ('loss', 'waste', 'gain')),
  `reason` VARCHAR(255),
  `status` VARCHAR(32) DEFAULT 'draft',
  CHECK (`status` IN ('draft', 'posted')),
  `goods_id` BIGINT NOT NULL,
  `qty` DECIMAL(12,2),
  CONSTRAINT `fk_stock_adjust_warehouse_id` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouse`(`id`),
  CONSTRAINT `fk_stock_adjust_goods_id` FOREIGN KEY (`goods_id`) REFERENCES `goods`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='库存调整';

-- ========== domain: delivery (配送管理) ==========
CREATE TABLE `carrier` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `name` VARCHAR(128),
  `phone` VARCHAR(32),
  `status` VARCHAR(32) DEFAULT 'normal' COMMENT '状态（lockable 自动派生）',
  CHECK (`status` IN ('normal', 'locked')),
  `lock_operator` VARCHAR(64) COMMENT '禁用操作人（lockable 自动派生）',
  `lock_time` DATETIME COMMENT '禁用时间（lockable 自动派生）'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='承运商';

CREATE TABLE `driver` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `name` VARCHAR(64),
  `phone` VARCHAR(32),
  `carrier_id` BIGINT NOT NULL,
  `id_card_no` VARCHAR(32) COMMENT '身份证号（加密存储）',
  `status` VARCHAR(32) DEFAULT 'normal' COMMENT '状态（lockable 自动派生）',
  CHECK (`status` IN ('normal', 'locked')),
  `lock_operator` VARCHAR(64) COMMENT '禁用操作人（lockable 自动派生）',
  `lock_time` DATETIME COMMENT '禁用时间（lockable 自动派生）',
  CONSTRAINT `fk_driver_carrier_id` FOREIGN KEY (`carrier_id`) REFERENCES `carrier`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='司机';

CREATE TABLE `route` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `name` VARCHAR(64),
  `route_type` VARCHAR(32) DEFAULT 'vegetable',
  CHECK (`route_type` IN ('breakfast', 'vegetable', 'meat', 'dry')),
  `carrier_id` BIGINT NOT NULL,
  `distance_km` DECIMAL(8,2) COMMENT '路线里程',
  `status` VARCHAR(32) DEFAULT 'normal',
  CHECK (`status` IN ('normal', 'locked')),
  CONSTRAINT `fk_route_carrier_id` FOREIGN KEY (`carrier_id`) REFERENCES `carrier`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='配送路线';

CREATE TABLE `route_bind` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `route_id` BIGINT NOT NULL,
  `customer_id` BIGINT NOT NULL,
  `driver_id` BIGINT NOT NULL,
  `vehicle_no` VARCHAR(16) COMMENT '车牌号',
  `gps_device_id` BIGINT NULL COMMENT '绑定 GPS 设备',
  `sort` INT DEFAULT 0 COMMENT '送达顺序',
  CONSTRAINT `fk_route_bind_route_id` FOREIGN KEY (`route_id`) REFERENCES `route`(`id`),
  CONSTRAINT `fk_route_bind_customer_id` FOREIGN KEY (`customer_id`) REFERENCES `customer`(`id`),
  CONSTRAINT `fk_route_bind_driver_id` FOREIGN KEY (`driver_id`) REFERENCES `driver`(`id`),
  CONSTRAINT `fk_route_bind_gps_device_id` FOREIGN KEY (`gps_device_id`) REFERENCES `gps_device`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='路线绑定';

CREATE TABLE `gps_device` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `device_no` VARCHAR(32) COMMENT '设备号',
  `plate_no` VARCHAR(16) COMMENT '绑定车牌',
  `device_status` VARCHAR(32) DEFAULT 'normal',
  CHECK (`device_status` IN ('normal', 'offline', 'disabled')),
  `last_login_time` DATETIME
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='GPS 设备';

CREATE TABLE `gps_alarm` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `device_id` BIGINT NOT NULL,
  `alarm_type` VARCHAR(32),
  CHECK (`alarm_type` IN ('track_deviation', 'temperature', 'late', 'out_of_area', 'into_forbidden')),
  `alarm_date` DATE,
  `content` VARCHAR(255) COMMENT '报警内容',
  `handled` TINYINT(1) DEFAULT 0,
  CONSTRAINT `fk_gps_alarm_device_id` FOREIGN KEY (`device_id`) REFERENCES `gps_device`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='GPS 报警';

CREATE TABLE `delivery_record` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `route_id` BIGINT NOT NULL,
  `delivery_date` DATE,
  `customer_id` BIGINT NOT NULL,
  `driver_id` BIGINT NOT NULL,
  `arrive_time` DATETIME COMMENT '送达时间',
  `mileage_km` DECIMAL(8,2) COMMENT '本段里程',
  `sign_status` VARCHAR(32) DEFAULT 'pending',
  CHECK (`sign_status` IN ('pending', 'signed', 'refused')),
  CONSTRAINT `fk_delivery_record_route_id` FOREIGN KEY (`route_id`) REFERENCES `route`(`id`),
  CONSTRAINT `fk_delivery_record_customer_id` FOREIGN KEY (`customer_id`) REFERENCES `customer`(`id`),
  CONSTRAINT `fk_delivery_record_driver_id` FOREIGN KEY (`driver_id`) REFERENCES `driver`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='配送执行记录';

-- ========== domain: settlement (结算管理) ==========
CREATE TABLE `settle_sheet` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `sheet_no` VARCHAR(32),
  `customer_id` BIGINT NOT NULL,
  `period_start` DATE COMMENT '账期起',
  `period_end` DATE COMMENT '账期止',
  `total_amount` DECIMAL(12,2) DEFAULT 0,
  `status` VARCHAR(32) DEFAULT 'draft',
  CHECK (`status` IN ('draft', 'confirmed', 'partial_paid', 'paid')),
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间（auditable 自动派生）',
  `created_by` VARCHAR(64) COMMENT '创建人（auditable 自动派生）',
  `updated_at` DATETIME COMMENT '更新时间（auditable 自动派生）',
  CONSTRAINT `fk_settle_sheet_customer_id` FOREIGN KEY (`customer_id`) REFERENCES `customer`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='对账单';

CREATE TABLE `settle_item` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `sheet_id` BIGINT NOT NULL,
  `order_id` BIGINT NOT NULL,
  `amount` DECIMAL(12,2),
  CONSTRAINT `fk_settle_item_sheet_id` FOREIGN KEY (`sheet_id`) REFERENCES `settle_sheet`(`id`),
  CONSTRAINT `fk_settle_item_order_id` FOREIGN KEY (`order_id`) REFERENCES `sales_order`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='对账明细';

CREATE TABLE `payment_record` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `customer_id` BIGINT NOT NULL,
  `settle_sheet_id` BIGINT NULL COMMENT '关联对账单',
  `amount` DECIMAL(12,2),
  `pay_method` VARCHAR(32) DEFAULT 'bank',
  CHECK (`pay_method` IN ('cash', 'bank', 'wechat', 'alipay')),
  `pay_time` DATETIME,
  `status` VARCHAR(32) DEFAULT 'pending',
  CHECK (`status` IN ('pending', 'success', 'failed')),
  CONSTRAINT `fk_payment_record_customer_id` FOREIGN KEY (`customer_id`) REFERENCES `customer`(`id`),
  CONSTRAINT `fk_payment_record_settle_sheet_id` FOREIGN KEY (`settle_sheet_id`) REFERENCES `settle_sheet`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='收款记录';

CREATE TABLE `supplier_payable` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `supplier_id` BIGINT NOT NULL,
  `period_start` DATE,
  `period_end` DATE,
  `amount` DECIMAL(12,2) DEFAULT 0,
  `status` VARCHAR(32) DEFAULT 'open',
  CHECK (`status` IN ('open', 'paid')),
  CONSTRAINT `fk_supplier_payable_supplier_id` FOREIGN KEY (`supplier_id`) REFERENCES `supplier`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='供应商应付';

-- ========== domain: traceability (溯源管理) ==========
CREATE TABLE `trace_batch` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `batch_no` VARCHAR(64) COMMENT '批次号',
  `goods_id` BIGINT NOT NULL,
  `supplier_id` BIGINT NOT NULL,
  `production_date` DATE COMMENT '生产/采摘日期',
  `in_date` DATE COMMENT '入库日期',
  `source_place` VARCHAR(128) COMMENT '产地',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `fk_trace_batch_goods_id` FOREIGN KEY (`goods_id`) REFERENCES `goods`(`id`),
  CONSTRAINT `fk_trace_batch_supplier_id` FOREIGN KEY (`supplier_id`) REFERENCES `supplier`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='溯源批次';

CREATE TABLE `inspect_report` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `report_no` VARCHAR(64),
  `batch_id` BIGINT NOT NULL,
  `report_date` DATE,
  `result` VARCHAR(32) DEFAULT 'pending',
  CHECK (`result` IN ('pending', 'pass', 'fail')),
  `items_json` JSON COMMENT '检测项与数值',
  `report_images` JSON COMMENT '报告图片 URL 列表',
  CONSTRAINT `fk_inspect_report_batch_id` FOREIGN KEY (`batch_id`) REFERENCES `trace_batch`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='检测报告';

CREATE TABLE `trace_setting` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `show_client` TINYINT(1) DEFAULT 1 COMMENT '公开页是否展示客户',
  `show_buy_num` TINYINT(1) DEFAULT 0 COMMENT '是否展示购买数量',
  `show_node_time` TINYINT(1) DEFAULT 1 COMMENT '是否展示流转时间',
  `qr_prefix` VARCHAR(128) COMMENT '扫码页 URL 前缀'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='溯源公开页设置';

-- ========== domain: system_admin (系统管理) ==========
CREATE TABLE `admin_user` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `username` VARCHAR(64) COMMENT '登录名（手机号/账号）',
  `name` VARCHAR(64) COMMENT '姓名',
  `phone` VARCHAR(32),
  `password_hash` VARCHAR(128) COMMENT '口令哈希（bcrypt/argon2）',
  `role_id` BIGINT NOT NULL,
  `status` VARCHAR(32) DEFAULT 'active',
  CHECK (`status` IN ('active', 'disabled')),
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `fk_admin_user_role_id` FOREIGN KEY (`role_id`) REFERENCES `sys_role`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='管理员';

CREATE TABLE `sys_module` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `code` VARCHAR(64) COMMENT '模块代码',
  `name` VARCHAR(64),
  `parent_id` BIGINT NULL COMMENT '父级模块',
  `sort` INT DEFAULT 0,
  CONSTRAINT `fk_sys_module_parent_id` FOREIGN KEY (`parent_id`) REFERENCES `sys_module`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='功能模块';

CREATE TABLE `sys_function` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `module_id` BIGINT NOT NULL,
  `code` VARCHAR(64) COMMENT '功能码',
  `name` VARCHAR(64),
  CONSTRAINT `fk_sys_function_module_id` FOREIGN KEY (`module_id`) REFERENCES `sys_module`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='功能点';

CREATE TABLE `sys_role` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `code` VARCHAR(64),
  `name` VARCHAR(64),
  `descr` VARCHAR(255)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='角色';

CREATE TABLE `sys_role_grant` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `role_id` BIGINT NOT NULL,
  `function_code` VARCHAR(64) COMMENT '授权的功能码',
  CONSTRAINT `fk_sys_role_grant_role_id` FOREIGN KEY (`role_id`) REFERENCES `sys_role`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='角色授权';

CREATE TABLE `sys_config` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `config_key` VARCHAR(64) COMMENT '参数键',
  `config_value` VARCHAR(255) COMMENT '参数值（敏感值须加密存储）',
  `description` VARCHAR(255)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='系统参数';

CREATE TABLE `operation_log` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  `user_id` BIGINT NOT NULL,
  `action` VARCHAR(64) COMMENT '动作，如 login/update/delete',
  `target_table` VARCHAR(64),
  `target_id` VARCHAR(64),
  `detail_json` JSON COMMENT '变更前后快照',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `fk_operation_log_user_id` FOREIGN KEY (`user_id`) REFERENCES `admin_user`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='操作日志';
